"use strict";
import { useState } from "react";
import { Flex, IconButton, Input } from "ui/src";
import { Search, X } from "ui/src/components/icons";
import { useSporeColors } from "ui/src/hooks/useSporeColors";
import { zIndexes } from "ui/src/theme";
export function AnimatedSearchBar({
  value,
  onChange,
  onClear,
  placeholder = "Search...",
  height = 40,
  collapsedWidth = 40,
  expandedWidth = "100%"
}) {
  const [isOpen, setIsOpen] = useState(false);
  const colors = useSporeColors();
  const handleFocus = () => setIsOpen(true);
  const handleBlur = () => {
    if (value === "") {
      setIsOpen(false);
    }
  };
  const handleClose = () => {
    onChange("");
    if (onClear) onClear();
    setIsOpen(false);
  };
  if (value && !isOpen) {
    setIsOpen(true);
  }
  return <Flex position="relative" height={height} zIndex={zIndexes.mask}>
      <Flex position={"absolute"} left={0} width={isOpen ? expandedWidth : collapsedWidth} height={height}>
        <Search
    fill={colors.neutral1.val}
    position={"absolute"}
    left={isOpen ? 12 : "50%"}
    top={"50%"}
    transform={isOpen ? "translate(0, -50%)" : "translate(-50%, -50%)"}
    size={20}
    pointerEvents="none"
  />
        <Input
    data-testid="animated-search-input"
    placeholder={placeholder}
    placeholderTextColor="$neutral3"
    autoComplete="off"
    value={value}
    onChangeText={onChange}
    backgroundColor="$surface1"
    borderRadius={12}
    borderWidth={1}
    borderColor={isOpen ? "$accent1" : "$surface3"}
    height="100%"
    width={isOpen ? "100%" : 0}
    pl={34}
    color="$neutral2"
    textOverflow="ellipsis"
    onFocus={handleFocus}
    onBlur={handleBlur}
    $platform-web={{
      transitionDuration: "200ms"
    }}
    focusStyle={{
      backgroundColor: "$surface1",
      borderColor: "$accent1",
      color: "$neutral1"
    }}
    hoverStyle={{
      backgroundColor: "$surface1"
    }}
  />
        {isOpen && <Flex row centered position="absolute" right={6} zIndex={zIndexes.mask}>
            <IconButton size="xxsmall" emphasis="secondary" onPress={handleClose} icon={<X />} p={3} scale={0.8} />
          </Flex>}
      </Flex>
    </Flex>;
}
